package org.bukkit.scheduler; public interface BukkitScheduler { BukkitTask runTaskTimer(org.bukkit.plugin.Plugin p, Runnable r, long d, long per); BukkitTask runTaskLater(org.bukkit.plugin.Plugin p, Runnable r, long d); BukkitTask runTaskAsynchronously(org.bukkit.plugin.Plugin p, Runnable r); BukkitTask runTaskTimerAsynchronously(org.bukkit.plugin.Plugin p, Runnable r, long d, long per); BukkitTask runTask(org.bukkit.plugin.Plugin p, Runnable r); void cancelTasks(org.bukkit.plugin.Plugin p); }
